changeSet.sql:
CREATE TABLE IF NOT EXISTS RSDEV1400_RemovedUserGroup ( id BIGINT NOT NULL, kept_id BIGINT NOT NULL, includePermissions BIT(1) NOT NULL, roleInGroup INT DEFAULT NULL, group_id BIGINT DEFAULT NULL, user_id BIGINT DEFAULT NULL, adminViewDocsEnabled BIT(1) NOT NULL, piCanEditWork TINYINT(1) NOT NULL, autoshareEnabled BIT(1) DEFAULT NULL, autoShareFolder_id BIGINT DEFAULT NULL, permissionStrings MEDIUMTEXT DEFAULT NULL, removedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id) ) ENGINE=InnoDB CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS RSDEV1400_RemovedRecordToFolder ( id BIGINT NOT NULL, kept_id BIGINT NOT NULL, recordInFolderDeleted BIT(1) DEFAULT NULL, userName VARCHAR(255) DEFAULT NULL, folder_id BIGINT DEFAULT NULL, record_id BIGINT DEFAULT NULL, deletedDate DATETIME DEFAULT NULL, removedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id) ) ENGINE=InnoDB CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT IGNORE INTO RSDEV1400_RemovedUserGroup (id, kept_id, includePermissions, roleInGroup, group_id, user_id, adminViewDocsEnabled, piCanEditWork, autoshareEnabled, autoShareFolder_id, permissionStrings) SELECT r.id, r.kept_id, r.includePermissions, r.roleInGroup, r.group_id, r.user_id, r.adminViewDocsEnabled, r.piCanEditWork, r.autoshareEnabled, r.autoShareFolder_id, r.permissionStrings FROM (SELECT ug.*, MIN(ug.id) OVER (PARTITION BY ug.group_id, ug.user_id) AS kept_id FROM UserGroup ug WHERE ug.group_id IS NOT NULL AND ug.user_id IS NOT NULL) r WHERE r.id <> r.kept_id;
DELETE ug FROM UserGroup ug JOIN RSDEV1400_RemovedUserGroup r ON r.id = ug.id;
INSERT IGNORE INTO RSDEV1400_RemovedRecordToFolder (id, kept_id, recordInFolderDeleted, userName, folder_id, record_id, deletedDate) SELECT r.id, r.kept_id, r.recordInFolderDeleted, r.userName, r.folder_id, r.record_id, r.deletedDate FROM (SELECT rf.*, MIN(rf.id) OVER (PARTITION BY rf.folder_id, rf.record_id) AS kept_id FROM RecordToFolder rf WHERE COALESCE(rf.recordInFolderDeleted, 0) = 0 AND rf.folder_id IS NOT NULL AND rf.record_id IN ( SELECT communalGroupFolderId FROM rsGroup WHERE communalGroupFolderId IS NOT NULL UNION SELECT sharedSnippetGroupFolderId FROM rsGroup WHERE sharedSnippetGroupFolderId IS NOT NULL UNION SELECT rootFolder_id FROM User WHERE rootFolder_id IS NOT NULL)) r WHERE r.id <> r.kept_id;
DELETE rf FROM RecordToFolder rf JOIN RSDEV1400_RemovedRecordToFolder r ON r.id = rf.id;
